import os

def get_file_content(base_dir, filename):
    """
    Retrieve file content from the specified directory.
    base_dir: the root directory to search in
    filename: the name of the file to retrieve
    """
    # Construct the full path from user input
    file_path = os.path.join(base_dir, filename)

    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()
        return {'status': 'success', 'content': content}
    except FileNotFoundError:
        return {'status': 'error', 'message': 'File not found'}
    except IOError as e:
        return {'status': 'error', 'message': str(e)}

# Example usage
result = get_file_content('/home/user/documents', '../../../etc/passwd')
print(result)
